bool replace(std::vector<int>& values, std::vector<int> candidate) { for (int x : candidate) if (x < 0) return false; values.swap(candidate); return true; }
int main() { std::vector<int> values{9}; std::cout << replace(values, {1, -2}) << ' ' << values[0] << '\n'; }

